effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _SourceTex_TexelSize (1.0 / vec2(textureSize(inputImg, 0)))
vec4 u_xlat0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec4 u_xlat2;
bvec4 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat13;
bvec2 u_xlatb13;
float u_xlat18;
void main()
{
    u_xlat0.xyz = _color.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat0.xyz = _color.xyz * u_xlat0.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat0.xyz = u_xlat0.xyz * _color.xyz;
    u_xlat1.xy = vec2(1.0, 1.0) / _SourceTex_TexelSize.xy;
    u_xlat13.xy = u_xlat1.xy * vec2(0.5, 0.5);
    u_xlat13.xy = ceil(u_xlat13.xy);
    u_xlat1.xy = acScreenNorm.xy * u_xlat1.xy + (-u_xlat13.xy);
    u_xlat2 = vec4(1.0, 1.0, 1.0, 1.0) / vec4(_cells1, _cells2, _cells1, _cells2);
    u_xlat2 = (-u_xlat2) + vec4(1.0, 1.0, 1.0, 1.0);
    u_xlat3 = u_xlat1.xxyy / vec4(_cells1, _cells2, _cells1, _cells2);
    u_xlat3 = fract(u_xlat3);
    u_xlatb2 = greaterThanEqual(u_xlat3, u_xlat2);
    u_xlat2.x = u_xlatb2.x ? float(1.0) : 0.0;
    u_xlat2.y = u_xlatb2.y ? float(1.0) : 0.0;
    u_xlat2.z = u_xlatb2.z ? float(1.0) : 0.0;
    u_xlat2.w = u_xlatb2.w ? float(1.0) : 0.0;
;
    u_xlat13.xy = u_xlat2.xy * vec2(_intensity1, _intensity2);
    u_xlat18 = u_xlat13.y + u_xlat13.x;
    u_xlat18 = u_xlat2.z * _intensity1 + u_xlat18;
    u_xlat2.w = u_xlat2.w * _intensity2 + u_xlat18;
    u_xlat3.xyz = u_xlat0.xyz * u_xlat2.www;
    u_xlatb13.xy = equal(ivec4(int(_show_axes), int(_blend_mode), int(_show_axes), int(_blend_mode)), ivec4(1, 1, 1, 1)).xy;
    u_xlat1.xy = abs(u_xlat1.xy) + vec2(-1.0, -1.0);
    u_xlatb1.xy = greaterThanEqual(vec4(0.0, 0.0, 0.0, 0.0), u_xlat1.xyxx).xy;
    u_xlat1.x = u_xlatb1.x ? float(1.0) : 0.0;
    u_xlat1.y = u_xlatb1.y ? float(1.0) : 0.0;
;
    u_xlat0.xyz = (-u_xlat2.www) * u_xlat0.xyz + vec3(0.963999987, 0.446999997, 0.442999989);
    u_xlat0.xyz = u_xlat1.xxx * u_xlat0.xyz + u_xlat3.xyz;
    u_xlat4.xyz = (-u_xlat0.xyz) + vec3(0.340999991, 0.800000012, 0.560000002);
    u_xlat0.xyz = u_xlat1.yyy * u_xlat4.xyz + u_xlat0.xyz;
    u_xlat2.xyz = (u_xlatb13.x) ? u_xlat0.xyz : u_xlat3.xyz;
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat3 = u_xlat0 * u_xlat2;
    u_xlat4.xyz = u_xlat0.xyz + u_xlat2.xyz;
    u_xlat4.w = u_xlat0.w;
    u_xlat1 = (u_xlatb13.y) ? u_xlat3 : u_xlat4;
    u_xlat3.xyz = u_xlat2.xyz;
    u_xlat1 = (int(_blend_mode) != 0) ? u_xlat1 : u_xlat3;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
